\begin{lemma}[Combined point measurements]
	\label{lem:qld-4-10}
	\lean{MIPStarRE.QPBT.CombinedPointsWitness}
	\lean{MIPStarRE.QPBT.exists_combinedPointsWitness}
	\leanok
	\uses{def:expanded-state, def:expanded-point-measurement,
		def:povm-distance, def:symmetric-equivalents}
	There exists a function $\delta_Q(\eps) = \poly(\eps)$ such that the
	following holds. For every $x, z \in \F_q^m$ and
	$\hilb \in \{\hilb_{\mathsf{A}}, \hilb_{\mathsf{B}}\}$ there are
	projective measurements $\{\hat{Q}^{x,z}_{a,b}\}_{a,b \in \F_q}$ acting
	on $\hilb \ot (\C^q)^{\ot M}$ such that:
	\begin{enumerate}
		\item (\textbf{Self-consistency}) On average over uniformly random
		$x, z \in \F_q^m$,
		\begin{equation}
			\label{eq:qld-q-self-cons}
			(\hat{Q}^{x,z}_{a,b})_{\mathsf{A}\mathsf{A}'}
			\approx_{\delta_Q}
			(\hat{Q}^{x,z}_{a,b})_{\mathsf{B}\mathsf{A}''}\,.
		\end{equation}
		\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly
		random $x, z \in \F_q^m$,
		\begin{gather}
			\label{eq:qld-q-cons-m-hat-xz}
			(\hat{Q}^{x,z}_{a,b})_{\mathsf{A}\mathsf{A}'}
			\approx_{\delta_Q}
			(\hat{M}^{(\mathrm{Point},X),x}_{a} \,
			\hat{M}^{(\mathrm{Point},Z),z}_{b})_{\mathsf{B}\mathsf{A}''}\,,
			\\
			\label{eq:qld-q-cons-m-hat-zx}
			(\hat{Q}^{x,z}_{a,b})_{\mathsf{A}\mathsf{A}'}
			\approx_{\delta_Q}
			(\hat{M}^{(\mathrm{Point},Z),z}_{b} \,
			\hat{M}^{(\mathrm{Point},X),x}_{a})_{\mathsf{B}\mathsf{A}''}\,.
		\end{gather}
	\end{enumerate}
	Furthermore, all symmetric equivalents of these approximations also hold.
	The operators $\hat{M}^{(\mathrm{Point},X),x}_{a}$ and
	$\hat{M}^{(\mathrm{Point},Z),z}_{b}$ do not commute in general, so the
	products in \eqref{eq:qld-q-cons-m-hat-xz} and
	\eqref{eq:qld-q-cons-m-hat-zx} differ and the two relations are separate
	conclusions.
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:qld-comm-cons, fact:agreement, lem:ortho,
		def:expanded-point-measurement, def:povm-distance}
	On each original expanded local space, form the $\F_q^2$-valued sandwich
	POVM $R^{x,z}_{a,b}=M^{(\mathrm{Point},Z),z}_{b}
	M^{(\mathrm{Point},X),x}_{a}M^{(\mathrm{Point},Z),z}_{b}$.
	The field-valued commutation estimate compares this POVM with both ordered
	products.  An exact overlap identity and the point-measurement consistency
	bounds give self-consistency of the two opposite placements.  Applying
	Lemma~\ref{lem:ortho} separately on the two player spaces produces
	projective measurements $\hat Q^{x,z}$ on those same spaces.  Their distance
	from the sandwiches, the ordered-product comparisons, and the triangle
	inequality give \eqref{eq:qld-q-self-cons},
	\eqref{eq:qld-q-cons-m-hat-xz}, and \eqref{eq:qld-q-cons-m-hat-zx}, with
	error $K\eps^{1/8}$ for a universal constant $K$.  Thus no common ancillary
	extension or invocation of Theorem~\ref{thm:linearity} is needed for this
	formalized construction; Remark~\ref{rem:linearity-import} records only the
	separate obstruction in the source's linearity-based route.
\end{proof}

\begin{lemma}[Formalization support: supplied combined-point marginals]
	\label{lem:supplied-combined-point-line-marginals}
	\lean{MIPStarRE.QPBT.exists_combinedPoints_line_marginal_distance_le}
	\leanok
